insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('CI', 'CI-P-18', 'Achats de biens 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 362-1° et 364 — déduction mensuelle, après exigibilité chez le fournisseur, de la taxe sur les achats affectés à des opérations taxées ou exportées ; art. 385 — facture portant les mentions de l''art. 384, et depuis le 1er décembre 2025 seule la facture normalisée électronique justifie la déduction', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-P-18-95', 'Gazole des engins du BTP et exploitants agricoles 18 %, déductible à 95 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 365, dans la rédaction de la loi de finances pour 2026, art. 38-2 — pour le gazole, les huiles et les graisses des engins des entreprises du bâtiment et des travaux publics et des exploitants agricoles ayant opté, la déduction est limitée à 95 % ; le reste est une part du coût', 'S', null, 150, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'annexe-fiscale-2026', null, null, null, null),
  ('CI', 'CI-P-18-IMMO', 'Immobilisations 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 365, 366 et 376 — déduction de la taxe sur les biens amortissables, dont la valeur nette est indiquée à part ; art. 375 — régularisation en cas de cession ou de changement d''affectation', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-P-18-ND', 'Achat 18 % non déductible (art. 372)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 372 — exclusions du droit à déduction, notamment l''hôtellerie et la restauration, les frais de représentation, le mobilier, les véhicules de tourisme de plus de 12 CV et le carburant hors transport public ; art. 373 — pas de déduction pour un achat de plus de 250 000 F réglé en espèces. La taxe est une part du coût', 'S', null, 160, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-P-18-SRV', 'Services extérieurs 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 362-1° et 364 — déduction après exigibilité chez le fournisseur, soit, pour un service, après son encaissement par le prestataire', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-P-9', 'Achats 9 %', '{}'::jsonb, null, 'percent', 9, 'purchase', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 359, alinéa 2 pour le taux ; art. 364 pour la déduction ; art. 382 — les opérations au taux réduit ouvrent droit au remboursement du crédit', 'S', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-P-IMP-18', 'Importation 18 % (TVA acquittée en douane)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'import', date '2018-01-01', null, 'Code général des impôts, art. 388 — à l''importation, le fait générateur est la mise à la consommation et le redevable le déclarant en douane ; la taxe payée en douane est déduite comme une autre, justifiée par la déclaration et la quittance (art. 386)', null, null, 170, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-P-NR-18', 'Services d''un non-résident 18 %, TVA pour compte de tiers', '{}'::jsonb, null, 'percent', 18, 'purchase', 'foreign_services_received', date '2018-01-01', null, 'Code général des impôts, art. 442 — la taxe due par une personne sans établissement stable en Côte d''Ivoire est acquittée par son représentant ou, à défaut, par le preneur, solidairement responsable. Elle se déclare sur la déclaration « TVA pour compte de Tiers » d''e-impots, distincte de la déclaration de TVA : la taxe retenue attend son reversement au compte 4478, sans case de ce formulaire, et sa déduction passe par la ligne 5.1', null, null, 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-S-18', 'Ventes de biens 18 %', '{}'::jsonb, 'Livraisons de biens au taux normal ; code TVA de la FNE', 'percent', 18, 'sale', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 359, alinéa 1 — taux de 18 % sur la base hors taxe, fixé par la loi de finances pour 2003 (loi n° 2003-206 du 7 juillet 2003, art. 3-1) ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau. La date de début retenue est celle à partir de laquelle ce pack décrit des livres, le SYSCOHADA révisé, et non celle du taux ; art. 361-1° et 2° — pour une livraison de biens, fait générateur et exigibilité à la livraison', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-S-18-SRV', 'Prestations de services 18 %, exigibles à l''encaissement', '{}'::jsonb, 'Prestations de services au taux normal, taxe due à l''encaissement', 'percent', 18, 'sale', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 359, alinéa 1 — taux de 18 % sur la base hors taxe, fixé par la loi de finances pour 2003 (loi n° 2003-206 du 7 juillet 2003, art. 3-1) ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau. La date de début retenue est celle à partir de laquelle ce pack décrit des livres, le SYSCOHADA révisé, et non celle du taux ; art. 361-2° — pour les prestations de services et les travaux immobiliers, la taxe est exigible à l''encaissement des avances, acomptes et du prix, sauf option pour les débits autorisée par le Directeur général des Impôts (art. 361-2° c). Facturée, la taxe attend l''encaissement au compte 4432 « T.V.A. facturée sur prestations de services » ; encaissée, elle est exigible et passe au compte 4431, dont l''intitulé « sur ventes » couvre les ventes de services du compte 706 : le plan n''a pas de compte de taxe en attente', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, true, '4432', 'cgi', null, null, null, null),
  ('CI', 'CI-S-9', 'Taux réduit 9 %', '{}'::jsonb, 'Biens de la liste de l''art. 359, alinéa 2 ; code TVAB de la FNE', 'percent', 9, 'sale', 'domestic', date '2018-01-01', null, 'Code général des impôts, art. 359, alinéa 2 — taux réduit de 9 % : lait et laits infantiles, pâtes alimentaires de blé dur, produits pétroliers, riz de luxe, viande de luxe (loi de finances pour 2025, art. 1er-4) et, depuis le 17 janvier 2026 (ordonnance n° 2026-03 du 7 janvier 2026), fibres de jute et de sisal, aliments pour bétail et leurs intrants, intrants des engrais ; la taxe sur ces derniers est suspendue du 1er juillet au 31 décembre 2026. Directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux réduit de 5 % à 10 % sur une liste communautaire', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-S-EXO-C', 'Exonération conventionnelle', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2018-01-01', null, 'Code général des impôts, art. 383 bis — exonérations conventionnelles et du Code des investissements, accordées sur attestation dont un sticker sécurisé accompagne chaque copie remise au fournisseur, qui joint à sa déclaration la liste nominative des clients exonérés. Code TVAC de la facture normalisée électronique', 'E', null, 60, 'vat', true, array['buyer_certificate']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-S-EXO-L', 'Exonération légale (art. 355)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2018-01-01', null, 'Code général des impôts, art. 355 — opérations exonérées ; art. 354 — pas de taxe facturée, la taxe d''amont n''étant ni déductible ni remboursable. Code TVAD de la facture normalisée électronique', 'E', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('CI', 'CI-S-EXP', 'Exportation exemptée', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2018-01-01', null, 'Code général des impôts, art. 356 — sont exemptés de la taxe les exportations de biens et les services assimilés à des exportations, dont l''art. 357 dresse la liste ; art. 366 et 369 — droit à déduction, art. 382-1 — remboursement du crédit', 'G', null, 40, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null)
on conflict (country, code) do update set
