insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('CI', 'CI-TVA', 'Déclaration de taxe sur la valeur ajoutée (e-impots)', array['month', 'quarter']::declaration_period[], 'month'::declaration_period, date '2018-01-01', null, 'Code général des impôts, art. 437 — la taxe du mois précédent est déclarée chaque mois ; la déclaration trimestrielle n''est admise que lorsque la taxe mensuelle due est inférieure à 25 000 F, et le régime trimestriel du réel simplifié (art. 394) est abrogé par la loi de finances pour 2023 : le mois est la règle de tous et le trimestre une dérogation tenant au montant dû. Les cases suivent les lignes 1.1 à 6.4 de la déclaration « Taxe sur la valeur ajoutée » d''e-impots, décrites par le guide utilisateur de juin 2019, seul document officiel publié qui les énumère ; un code de ligne à point, que le format ne peut pas porter, perd son point (1.1 devient 11) et chaque case nomme la ligne imprimée. Paiement joint à la déclaration (art. 439).', true,null, null, null, null, null, null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
