update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Livre de procédures fiscales, art. 145, dans la rédaction de la loi de finances pour 2025, art. 6-8 — numérotation dans une série ininterrompue ; arrêté n° 0337 du 9 mai 2025, art. 5 — le numéro de la facture normalisée électronique est composé du numéro de compte contribuable, de l''année d''édition et d''une séquence annuelle ininterrompue, et c''est la plateforme de la DGI qui l''attribue. Le format déclaré ici est celui de la pièce comptable ; le numéro de la FNE est une donnée de la plateforme.',
  numbering_source_key          = 'arrete-fne',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Code général des impôts, art. 361-1° et 2° — pour une livraison de biens, le fait générateur et l''exigibilité sont la livraison ; pour une prestation de services ou des travaux immobiliers, la taxe est exigible à l''encaissement, sauf option pour les débits. delivery_date dit la règle des biens ; celle des services est portée par les taxes de service de ce pack, en cash_basis, et non par un second fait générateur du pays.',
  tax_point_source_key          = 'cgi',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Code général des impôts, art. 384, et Livre de procédures fiscales, art. 13 bis à 13 sexies, 144 et 145, dans la rédaction de la loi de finances pour 2025 (loi n° 2024-1109 du 18 décembre 2024, art. 6) — facture normalisée électronique (FNE) obligatoire pour toute livraison et toute prestation ; arrêté n° 0337 du 9 mai 2025, art. 3, 4 et 8 — émission sur la plateforme de la DGI ou par interfaçage API, sticker électronique composé du visuel FNE, d''un QR code et du numéro, obligation au plus tard le 1er juin 2025 pour le réel normal, le 1er juillet 2025 pour le réel simplifié, le 1er août 2025 pour les microentreprises et le 1er septembre 2025 pour les entreprenants ; fin de la facture normalisée papier le 1er décembre 2025 pour les régimes réels. La FNE n''est pas un profil de la norme EN 16931 et son API (codes TVA, TVAB, TVAC, TVAD) n''est lue par aucune brique : le profil reste vide et la date avec lui, faute de profil à rendre obligatoire. L''identifiant fiscal est le numéro de compte contribuable (NCC), sept chiffres et une lettre, sans code ISO 6523.',
  einvoice_source_key           = 'arrete-fne',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'CI';
